"use client";

import { useState, useRef } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { MessageSquare, Edit3, Save, Upload, X, ExternalLink, Plus } from 'lucide-react';
import { Input } from '@/components/ui/input';
import type { CommissionLink } from '@/lib/types';

const LINK_EMOJIS = ['💖', '✨', '❄️', '🌸', '🎨', '🍀', '🌟', '🌷', '🎀', '⛄', '❤️'];

function CommissionLinkButton({ link }: { link: CommissionLink }) {
  const [imgError, setImgError] = useState(() => {
    try {
      const urlObj = new URL(link.url);
      // 오픈카톡 등 특정 사이트는 파비콘 대신 이모지 강제 출력
      if (urlObj.hostname.includes('open.kakao.com') || urlObj.hostname.includes('kakao.com')) {
        return true;
      }
      return false;
    } catch (e) {
      return true;
    }
  });
  
  const getRandomEmoji = (url: string) => {
    let hash = 0;
    for (let i = 0; i < url.length; i++) {
        hash = url.charCodeAt(i) + ((hash << 5) - hash);
    }
    return LINK_EMOJIS[Math.abs(hash) % LINK_EMOJIS.length];
  };

  const faviconUrl = `https://t1.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=${encodeURIComponent(link.url)}&size=64`;

  return (
    <a 
      href={link.url} 
      target="_blank"  
      title={link.title || '외부 링크'}
      rel="norenoopener noreferrer"
      className="group flex items-center justify-center w-16 h-16 bg-card border border-border rounded-2xl shadow-sm hover:shadow-md hover:border-primary hover:bg-primary/5 transition-all duration-300 hover:-translate-y-1"
    >
      {!imgError ? (
        <img 
          src={faviconUrl} 
          alt={`${link.title || 'Link'} logo`} 
          className="w-8 h-8 object-contain"
          onError={() => setImgError(true)}
        />
      ) : (
        <span className="text-3xl leading-none">{getRandomEmoji(link.url)}</span>
      )}
    </a>
  );
}

export default function CommissionPage() {
  const { commissionInfo, setCommissionInfo, isAdmin } = useAppStore();
  const [isEditing, setIsEditing] = useState(false);
  const [content, setContent] = useState(commissionInfo.content);
  const [images, setImages] = useState<string[]>(commissionInfo.images);
  const [externalLinks, setExternalLinks] = useState<CommissionLink[]>(commissionInfo.externalLinks || []);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const addExternalLink = () => {
    setExternalLinks([...externalLinks, { title: '', url: '' }]);
  };

  const updateExternalLink = (index: number, field: keyof CommissionLink, value: string) => {
    const newLinks = [...externalLinks];
    newLinks[index][field] = value;
    setExternalLinks(newLinks);
  };

  const removeExternalLink = (index: number) => {
    setExternalLinks(externalLinks.filter((_, i) => i !== index));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    
    files.forEach((file) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const result = event.target?.result as string;
        setImages(prev => [...prev, result]);
      };
      reader.readAsDataURL(file);
    });
  };

  const removeImage = (index: number) => {
    setImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSave = async () => {
    setIsSaving(true);
    
    await new Promise(resolve => setTimeout(resolve, 500));
    
    setCommissionInfo({
      ...commissionInfo,
      content,
      images,
      externalLinks,
      updatedAt: new Date().toISOString(),
    });
    
    setIsSaving(false);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setContent(commissionInfo.content);
    setImages(commissionInfo.images);
    setExternalLinks(commissionInfo.externalLinks || []);
    setIsEditing(false);
  };

  return (
    <div className="min-h-screen bg-background">
      <Sidebar />
      
      <main className="min-h-screen transition-all duration-300 pt-16 lg:pt-0">
        <div className="max-w-4xl mx-auto px-6 py-12">
          {/* Header */}
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-primary/20 flex items-center justify-center">
                <MessageSquare className="w-5 h-5 text-primary" />
              </div>
              <div>
                <h1 className="text-2xl font-bold">커미션 신청</h1>
                <p className="text-sm text-muted-foreground">Commission Request</p>
              </div>
            </div>
            
            {isAdmin && !isEditing && (
              <Button onClick={() => setIsEditing(true)} variant="outline">
                <Edit3 className="w-4 h-4 mr-2" />
                편집
              </Button>
            )}
          </div>

          {/* Content */}
          <div className="rounded-2xl bg-card border border-border overflow-hidden">
            {isEditing ? (
              /* Edit Mode */
              <div className="p-6 space-y-6">
                <div className="flex items-center justify-between">
                  <h2 className="text-lg font-semibold">커미션 안내 편집</h2>
                  <span className="text-xs px-2 py-1 rounded-full bg-primary/20 text-primary font-medium">
                    관리자
                  </span>
                </div>

                {/* Content Editor */}
                <div className="space-y-2">
                  <Label htmlFor="commission-content">안내 내용</Label>
                  <Textarea
                    id="commission-content"
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    placeholder="커미션 안내 내용을 작성하세요..."
                    rows={10}
                    className="resize-none bg-input font-sans"
                  />
                  <p className="text-xs text-muted-foreground">
                    마크다운 형식을 지원합니다.
                  </p>
                </div>

                {/* Images */}
                <div className="space-y-2">
                  <Label>이미지 (webp, jpg, png, apng, gif, mp4 등)</Label>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept=".webp,.jpg,.jpeg,.png,.apng,.gif,.mp4,image/*,video/mp4"
                    multiple
                    onChange={handleImageUpload}
                    className="hidden"
                  />
                  
                  <div className="grid grid-cols-3 gap-2">
                    {images.map((img, index) => (
                      <div key={index} className="relative aspect-video rounded-lg overflow-hidden bg-muted">
                        <img src={img} alt={`이미지 ${index + 1}`} className="w-full h-full object-cover" />
                        <button
                          type="button"
                          onClick={() => removeImage(index)}
                          className="absolute top-1 right-1 p-1 rounded-full bg-destructive text-destructive-foreground"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    ))}
                    
                    <button
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                      className="aspect-video rounded-lg border-2 border-dashed border-border hover:border-primary flex flex-col items-center justify-center gap-1 transition-colors"
                    >
                      <Upload className="w-5 h-5 text-muted-foreground" />
                      <span className="text-xs text-muted-foreground">추가</span>
                    </button>
                  </div>
                </div>

                {/* External Links */}
                <div className="space-y-4 pt-2">
                  <div className="flex items-center justify-between">
                    <Label>외부 링크 첨부 (선택)</Label>
                    <Button type="button" variant="outline" size="sm" onClick={addExternalLink}>
                      <Plus className="w-4 h-4 mr-2" />
                      링크 추가
                    </Button>
                  </div>
                  
                  {externalLinks.map((link, index) => (
                    <div key={index} className="flex gap-2 items-start bg-muted/50 p-3 rounded-xl border border-border">
                      <div className="flex-1 space-y-3">
                        <div className="space-y-1">
                          <Label className="text-xs">버튼명</Label>
                          <Input
                            value={link.title}
                            onChange={(e) => updateExternalLink(index, 'title', e.target.value)}
                            placeholder="예: 크레페 링크, 오픈카톡 신청하기"
                            className="bg-background h-8 text-sm"
                          />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">URL 주소</Label>
                          <Input
                            type="url"
                            value={link.url}
                            onChange={(e) => updateExternalLink(index, 'url', e.target.value)}
                            placeholder="https://..."
                            className="bg-background h-8 text-sm"
                          />
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={() => removeExternalLink(index)}
                        className="p-1.5 mt-6 rounded-lg bg-destructive/10 text-destructive hover:bg-destructive hover:text-destructive-foreground transition-colors"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                  
                  {externalLinks.length === 0 && (
                    <div className="text-center p-4 border border-dashed border-border rounded-xl text-sm text-muted-foreground bg-muted/30">
                      추가된 링크가 없습니다. '링크 추가' 버튼을 눌러 오픈카톡이나 크레페 등의 링크를 달아보세요.
                    </div>
                  )}
                </div>

                {/* Actions */}
                <div className="flex justify-end gap-2 pt-4 border-t border-border">
                  <Button variant="outline" onClick={handleCancel}>
                    취소
                  </Button>
                  <Button onClick={handleSave} disabled={isSaving}>
                    <Save className="w-4 h-4 mr-2" />
                    {isSaving ? '저장 중...' : '저장'}
                  </Button>
                </div>
              </div>
            ) : (
              /* View Mode */
              <div className="p-6">
                {/* Commission Content */}
                <div className="prose prose-sm max-w-none mb-6">
                  <div className="whitespace-pre-wrap text-foreground leading-relaxed">
                    {commissionInfo.content}
                  </div>
                </div>

                {/* Images */}
                {commissionInfo.images.length > 0 && (
                  <div className="space-y-4">
                    <h3 className="text-sm font-medium text-muted-foreground">참고 이미지</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {commissionInfo.images.map((img, index) => (
                        <div key={index} className="rounded-xl overflow-hidden bg-muted">
                          <img 
                            src={img} 
                            alt={`커미션 참고 이미지 ${index + 1}`} 
                            className="w-full h-auto"
                          />
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Redirect Link Buttons */}
                {commissionInfo.externalLinks && commissionInfo.externalLinks.length > 0 && (
                  <div className="mt-10 flex flex-col md:flex-row justify-center gap-4 flex-wrap">
                    {commissionInfo.externalLinks.map((link, index) => (
                      <CommissionLinkButton key={index} link={link} />
                    ))}
                  </div>
                )}

                {/* Last Updated */}
                <div className="mt-8 pt-4 border-t border-border">
                  <p className="text-xs text-muted-foreground">
                    마지막 업데이트: {new Date(commissionInfo.updatedAt).toLocaleDateString('ko-KR')}
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Contact Info Card */}
          <div className="mt-6 p-6 rounded-2xl bg-primary/10 border border-primary/20">
            <h3 className="font-semibold mb-2">문의하기</h3>
            <p className="text-sm text-muted-foreground">
              커미션 관련 문의는 프로필 페이지의 AI 챗봇을 통해 기본적인 안내를 받으시거나,
              직접 연락주시면 됩니다.
            </p>
          </div>
        </div>
      </main>
    </div>
  );
}
